package ar.gob.municipalidad.rentas;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.OffsetDateTime;
import java.util.List;

@Service
class CreditBalanceService {
    private final CreditBalanceRepository credits;private final CreditBalanceApplicationRepository applications;private final DebtRepository debts;private final PaymentPlanRepository plans;private final EventosDeDominio events;private final CurrentIdentity identity;private final AuditService audit;
    private final PaymentPlanDebtRepository planDebts;private final BillLifecycleService billLifecycle;
    CreditBalanceService(CreditBalanceRepository credits,CreditBalanceApplicationRepository applications,DebtRepository debts,PaymentPlanRepository plans,EventosDeDominio events,CurrentIdentity identity,AuditService audit,PaymentPlanDebtRepository planDebts,BillLifecycleService billLifecycle){this.credits=credits;this.applications=applications;this.debts=debts;this.plans=plans;this.events=events;this.identity=identity;this.audit=audit;this.planDebts=planDebts;this.billLifecycle=billLifecycle;}
    void requireNoPaymentCredit(Long paymentId){CatalogService.require(credits.findBySourcePaymentId(paymentId).isEmpty(),"PAYMENT_BALANCE_CONVERTED_TO_CREDIT","El saldo no imputado del pago ya fue convertido en saldo a favor");}
    void createFromPayment(Payment payment,BigDecimal amount){CreditBalance credit=new CreditBalance();credit.taxpayerId=payment.taxpayerId;credit.sourcePaymentId=payment.id;credit.originalAmount=credit.availableAmount=amount;credit.status=CreditBalanceStatus.AVAILABLE;credit.createdAt=credit.updatedAt=OffsetDateTime.now();credits.save(credit);audit.record("CreditBalance",credit.id,"CREDIT_BALANCE_CREATED",credit);}
    @Transactional(readOnly=true) List<CreditBalanceApplication> applications(Long creditId){CreditBalance credit=credits.findById(creditId).orElseThrow(()->CatalogService.notFound("Saldo a favor"));identity.requireOwnership(credit.taxpayerId);return applications.findByCreditBalanceIdOrderByAppliedAtAscIdAsc(credit.id);}
    @Transactional CreditBalanceApplication apply(Long creditId,ApiDtos.ApplyCreditBalanceRequest request){return apply(creditId,request,null);}
    @Transactional CreditBalanceApplication apply(Long creditId,ApiDtos.ApplyCreditBalanceRequest request,String ifMatch){CreditBalance credit=credits.findByIdForUpdate(creditId).orElseThrow(()->CatalogService.notFound("Saldo a favor"));EntityTags.requireIfMatch(EntityTags.creditBalance(ApiResponses.of(credit)),ifMatch);Debt debt=debts.findByIdForUpdate(request.debtId()).orElseThrow(()->CatalogService.notFound("Deuda"));CatalogService.require(credit.taxpayerId.equals(debt.taxpayerId),"CREDIT_TAXPAYER_MISMATCH","El saldo y la deuda pertenecen a contribuyentes distintos");CatalogService.requireConflict(debt.admiteCobro(),"DEBT_NOT_PAYABLE","La deuda no admite pagos");CatalogService.requireConflict(!plans.existsByDebtIdAndStatus(debt.id,PaymentPlanStatus.ACTIVE)&&!planDebts.existsByDebtIdAndStatus(debt.id,PaymentPlanDebtStatus.ACTIVE),"DEBT_IN_ACTIVE_PAYMENT_PLAN","La deuda pertenece a un plan activo");BigDecimal amount=PaymentService.money(request.amount());CatalogService.require(amount.compareTo(credit.availableAmount)<=0,"INSUFFICIENT_CREDIT_BALANCE","El saldo a favor es insuficiente");CatalogService.require(amount.compareTo(debt.outstandingBalance)<=0,"CREDIT_EXCEEDS_DEBT","La aplicación supera el saldo de deuda");List<Bill> affectedBills=billLifecycle.lockForDebtBalanceChange(List.of(debt.id));CreditBalanceApplication a=new CreditBalanceApplication();a.creditBalanceId=credit.id;a.debtId=debt.id;a.amount=amount;a.status="ACTIVE";a.appliedBy=identity.get().userId();a.appliedAt=OffsetDateTime.now();applications.save(a);credit.availableAmount=credit.availableAmount.subtract(amount);credit.status=credit.availableAmount.signum()==0?CreditBalanceStatus.USED:CreditBalanceStatus.PARTIALLY_USED;credit.updatedAt=OffsetDateTime.now();debt.imputar(amount);debt.updatedAt=OffsetDateTime.now();if(debt.status==DebtStatus.PAID)events.deudaSaldada(debt);audit.record("CreditBalanceApplication",a.id,"CREDIT_BALANCE_APPLIED",a);billLifecycle.cancelForDebtBalanceChange(List.of(debt.id),affectedBills);return a;}
}
